import React, { useEffect, useState } from "react";
import { auth } from "../../firebase";
import { useNavigate } from "react-router-dom";
import NavBar from "../../Components/AdminNav";
import "./adminDashboard.css";

export default function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [editEmail, setEditEmail] = useState("");
  const [viewingUser, setViewingUser] = useState(null);
  const [acceptedCourses, setAcceptedCourses] = useState({}); 

  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 10;

  const navigate = useNavigate();
  const API_BASE_URL = "http://localhost:5000";

  useEffect(() => {
    const user = auth.currentUser;
    if (!user || user.email !== "yasasmigunasinghe@gmail.com") {
      navigate("/account");
    }
  }, [navigate]);

  const fetchUsers = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users`);
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to fetch users: ${res.status} ${text}`);
      }
      const data = await res.json();
      setUsers(data);
      setCurrentPage(1);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (uid) => {
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users/${uid}`, {method: "DELETE"});
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to delete user: ${res.status} ${text}`);
      }
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  const startEdit = (user) => {
    setEditingUser(user);
    setEditEmail(user.email);
  };

  const cancelEdit = () => {
    setEditingUser(null);
    setError("");
  };

  const submitEdit = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${editingUser.uid}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: editEmail }),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to update user: ${res.status} ${text}`);
      }
      setEditingUser(null);
      fetchUsers();
    } catch (err) {
      setError(err.message);
    }
  };

  const [currentCourses] = useState(["Skirt", "Blouse", "Frock", "Shirt", "Pant", "Kids"]); 

  const handleView = (user) => {
    setViewingUser(user);
    setAcceptedCourses(prev => ({
      ...prev,
      [user.uid]: prev[user.uid] || [] 
    }));
  };

  const acceptCourse = async (course) => {
    try {
      const res = await fetch(`${API_BASE_URL}/users/${viewingUser.uid}/accept-course`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ course }),
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to accept course: ${res.status} ${text}`);
      }
      setAcceptedCourses(prev => ({
        ...prev,
        [viewingUser.uid]: [...(prev[viewingUser.uid] || []), course]
      }));
    } catch (err) {
      setError(err.message);
    }
  };

  const closeViewModal = () => {
    setViewingUser(null);
    setError("");
  };

  // Pagination logic
  const totalPages = Math.ceil(users.length / usersPerPage);
  const startIndex = (currentPage - 1) * usersPerPage;
  const currentUsers = users.slice(startIndex, startIndex + usersPerPage);

  return (
    <>
      <NavBar />
      <div className="admin-container">
        <h2>Admin User Management</h2>
        {error && <p className="error-message">{error}</p>}
        {loading ? (
          <p>Loading users...</p>
        ) : (
          <>
            <table className="admin-table">
              <thead><tr>
                <th>Email</th><th>Username</th><th>WhatsApp Number</th><th>Accepted</th><th>Actions</th>
              </tr></thead>
              <tbody>
                {currentUsers.length === 0 ? (
                  <tr><td colSpan="5" style={{ textAlign: "center" }}>No users found</td></tr>
                ) : (
                  currentUsers.map((user) => (
                    <tr key={user.uid}>
                      <td>{user.email}</td>
                      <td>{user.username || "-"}</td>
                      <td>{user.whatsapp || "-"}</td>
                      <td>{user.accepted ? "Yes" : "No"}</td>
                      <td>
                        <div className="action-buttons">
                          <button className="btn-edit" onClick={() => startEdit(user)}>Edit</button>
                          <button className="btn-delete" onClick={() => handleDelete(user.uid)}>Delete</button>
                        </div>
                        {!user.accepted && (
                          <button className="btn-accept" onClick={() => handleView(user)}>View</button>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>

            {/* Pagination Controls */}
            <div className="pagination-controls" style={{ marginTop: "1rem", textAlign: "center" }}>
              <button onClick={() => currentPage > 1 && setCurrentPage(currentPage -1)} disabled={currentPage === 1}>Back</button>
              <span style={{ margin: "0 1rem" }}>Page {currentPage} of {totalPages}</span>
              <button onClick={() => currentPage < totalPages && setCurrentPage(currentPage +1)} disabled={currentPage === totalPages}>Next</button>
            </div>
          </>
        )}

        {/* Edit Modal */}
        {editingUser && (
          <div className="modal-overlay">
            <div className="modal-content">
              <h3>Edit User</h3>
              <input type="email" value={editEmail} onChange={(e) => setEditEmail(e.target.value)} />
              <div className="modal-buttons">
                <button className="btn-save" onClick={submitEdit}>Save</button>
                <button className="btn-cancel" onClick={cancelEdit}>Cancel</button>
              </div>
            </div>
          </div>
        )}

        {/* View Modal */}
        {viewingUser && (
          <div className="modal-overlay">
            <div className="modal-content">
              <h3>User Details</h3>
              <p><strong>Username: </strong>{viewingUser.username}</p>
              <p><strong>Email: </strong>{viewingUser.email}</p>
              <p><strong>WhatsApp: </strong>{viewingUser.whatsapp}</p>

              <div className="course-accept-buttons">
                {currentCourses.map((course) => {
                  const accepted = acceptedCourses[viewingUser.uid]?.includes(course);
                  return (
                    <button
                      key={course}
                      className="btn-course-accept"
                      disabled={accepted}
                      onClick={() => acceptCourse(course)}
                      style={{
                        background: "none",
                        border: "1px solid #ccc",
                        margin: "0 5px",
                        padding: "5px 10px",
                        cursor: accepted ? "not-allowed" : "pointer"
                      }}
                    >
                      {accepted ? `Accepted ${course}` : `Accept ${course}`}
                    </button>
                  )
                })}
              </div>
              <button onClick={closeViewModal} className="btn-cancel" style={{marginTop: "1rem"}}>Close</button>
            </div>
          </div>
        )}
      </div>
    </>
  );
}
